const config = $input.first().json;
const errors = [];
const ua = 'SilentCPO-ProjectFinder/1.0 (hello@silentcpo.me)';
const httpRequest = this.helpers.httpRequest.bind(this.helpers);

function strip(html) {
  return String(html || '')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#0?39;/g, "'")
    .replace(/&#x2F;/gi, '/')
    .replace(/&nbsp;/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function unpack(response) {
  if (response == null || response === '') return { statusCode: 0, body: null };
  if (typeof response === 'string') {
    const trimmed = response.trim();
    if (!trimmed) return { statusCode: 0, body: null };
    try { return { statusCode: 200, body: JSON.parse(trimmed) }; }
    catch { return { statusCode: 200, body: trimmed }; }
  }
  if (typeof response !== 'object') return { statusCode: 200, body: response };
  if (('statusCode' in response) && ('body' in response || 'data' in response)) {
    let body = response.body != null ? response.body : response.data;
    if (typeof body === 'string') {
      try { body = JSON.parse(body); } catch { /* keep text */ }
    }
    return { statusCode: Number(response.statusCode) || 0, body };
  }
  return { statusCode: 200, body: response };
}

function shapeOf(body) {
  if (body == null) return 'empty';
  if (typeof body === 'string') return 'text:' + body.slice(0, 80).replace(/\s+/g, ' ');
  if (Array.isArray(body)) return 'array:' + body.length;
  if (typeof body === 'object') return 'keys:' + Object.keys(body).slice(0, 8).join(',');
  return typeof body;
}

async function fetchJson(url, headers = {}) {
  const label = url.split('?')[0].replace('https://', '');
  if (typeof fetch === 'function') {
    try {
      const res = await fetch(url, {
        headers: { 'User-Agent': ua, Accept: 'application/json', ...headers },
      });
      const text = await res.text();
      if (!res.ok) {
        errors.push(label + ': ' + res.status + ' ' + text.slice(0, 140).replace(/\s+/g, ' '));
        return null;
      }
      try {
        return JSON.parse(text);
      } catch {
        errors.push(label + ': not json ' + text.slice(0, 80).replace(/\s+/g, ' '));
        return null;
      }
    } catch (error) {
      const message = error.message || String(error);
      if (!/fetch is not defined|fetch is not a function/i.test(message)) {
        errors.push(label + ': ' + message);
        return null;
      }
    }
  }
  try {
    const response = await httpRequest({
      method: 'GET',
      url,
      timeout: 20000,
      json: true,
      headers: { 'User-Agent': ua, Accept: 'application/json', ...headers },
    });
    const unpacked = unpack(response);
    if (unpacked.body == null || unpacked.body === '') {
      errors.push(label + ': empty (' + shapeOf(response) + ')');
      return null;
    }
    if (unpacked.statusCode >= 400) {
      const message = unpacked.body.message || unpacked.body.error || unpacked.body.status || unpacked.statusCode;
      errors.push(label + ': ' + unpacked.statusCode + ' ' + message);
      return null;
    }
    return unpacked.body;
  } catch (error) {
    errors.push(label + ': ' + (error.message || String(error)));
    return null;
  }
}

function parseAtom(xml) {
  return String(xml).split('<entry>').slice(1).map((chunk) => {
    const title = strip((chunk.match(/<title[^>]*>([\s\S]*?)<\/title>/) || [])[1] || '');
    const href = (chunk.match(/<link[^>]*href="([^"]+)"/) || [])[1] || '';
    const updated = (chunk.match(/<updated>([^<]+)<\/updated>/) || [])[1] || '';
    const content = strip((chunk.match(/<content[^>]*>([\s\S]*?)<\/content>/) || [])[1] || '');
    return { title, href, updated, content };
  }).filter((entry) => entry.title && entry.href);
}

const listings = [];
const seen = new Set();
function cleanUrl(value) {
  let raw = String(value || '').trim().split('#')[0];
  if (!raw.startsWith('https://')) return '';
  const q = raw.indexOf('?');
  const base = (q === -1 ? raw : raw.slice(0, q)).replace(/\/$/, '');
  if (q === -1) return base;
  const kept = raw.slice(q + 1).split('&').filter((part) => {
    const key = part.split('=')[0];
    return key && key.slice(0, 4) !== 'utm_' && key !== 'ref';
  });
  return kept.length ? base + '?' + kept.join('&') : base;
}

function add(item) {
  const url = cleanUrl(item.url);
  if (!url || seen.has(url)) return;
  seen.add(url);
  listings.push({
    source: item.source,
    title: String(item.title || '').slice(0, 180),
    url,
    createdAt: item.createdAt || '',
    text: String(item.text || '').slice(0, 900),
  });
}

const buildish = /website|web ?app|shopify|wordpress|developer|software|mobile app|\bapp\b|automation|react|next\.?js|booking|membership|\bsaas\b|\bmvp\b|full[- ]stack|frontend|backend|\bapi\b|\bpwa\b|e-?commerce/i;
const junk = /virtual assistant|voice recording|\bsales\b|3d print|rule34|onlyfans|crypto|forex|sports data|get paid to talk/i;
const freelancerToken = String(config.freelancerToken || '').trim();
const freelancerHeaders = freelancerToken ? { 'Freelancer-OAuth-V1': freelancerToken } : {};
const freelancerQueries = [
  'website', 'web app', 'shopify', 'booking system', 'membership site',
  'mobile app', 'mvp', 'saas', 'n8n', 'automation',
];
let freelancerRows = 0;
for (const query of freelancerQueries) {
  const data = await fetchJson(
    'https://www.freelancer.com/api/projects/0.1/projects/active/?limit=15&compact=true&query=' + encodeURIComponent(query),
    freelancerHeaders
  );
  const projectList = Array.isArray(data?.result?.projects) ? data.result.projects : [];
  if (!projectList.length) {
    errors.push('Freelancer ' + query + ': ' + shapeOf(data));
    continue;
  }
  let addedForQuery = 0;
  for (const project of projectList) {
    if (addedForQuery >= 3) break;
    if (!project || typeof project !== 'object') continue;
    const title = String(project.title || '').trim();
    const slug = String(project.seo_url || '').replace(/^\//, '');
    const id = project.id ? String(project.id) : '';
    if (!title || (!slug && !id)) continue;
    const text = strip(project.preview_description || project.description || '');
    if (junk.test(title + ' ' + text)) continue;
    const minimum = project.budget?.minimum;
    const maximum = project.budget?.maximum;
    const currency = project.currency?.code || '';
    const budget = minimum != null && maximum != null ? String(minimum) + '-' + String(maximum) + ' ' + currency : '';
    const before = listings.length;
    add({
      source: 'Freelancer',
      title,
      url: 'https://www.freelancer.com/projects/' + (slug || id),
      createdAt: project.time_submitted ? new Date(Number(project.time_submitted) * 1000).toISOString() : '',
      text: [budget ? 'Budget: ' + budget.trim() : '', text].filter(Boolean).join(' '),
    });
    if (listings.length > before) {
      freelancerRows += 1;
      addedForQuery += 1;
    }
  }
}
if (!freelancerRows) errors.push('Freelancer returned no usable projects');

const stories = await fetchJson(
  'https://hn.algolia.com/api/v1/search_by_date?query=' + encodeURIComponent('Ask HN: Freelancer? Seeking freelancer?') + '&tags=story&hitsPerPage=1'
);
const story = stories?.hits?.[0];
if (story?.objectID) {
  const comments = await fetchJson(
    'https://hn.algolia.com/api/v1/search_by_date?tags=comment,story_' + story.objectID + '&hitsPerPage=80'
  );
  for (const hit of comments?.hits || []) {
    const text = strip(hit.comment_text);
    if (!/^seeking freelancer\b/i.test(text)) continue;
    add({
      source: 'Hacker News',
      title: text.slice(0, 140),
      url: 'https://news.ycombinator.com/item?id=' + hit.objectID,
      createdAt: hit.created_at || '',
      text,
    });
  }
}

const github = await fetchJson(
  'https://api.github.com/search/issues?q=' + encodeURIComponent('is:issue is:open label:bounty -repo:claude-builders-bounty/claude-builders-bounty -repo:Scottcjn/rustchain-bounties') + '&sort=updated&per_page=8',
  { Accept: 'application/vnd.github+json' }
);
const githubItems = github?.items || github?.body?.items || [];
if (!githubItems.length) errors.push('GitHub: ' + (github?.message || shapeOf(github)));
for (const issue of githubItems) {
  const title = issue.title || '';
  const body = strip(issue.body || '');
  if (/star our|upvote|follow us|clawhub|youtube|badge to|honest review/i.test(title + ' ' + body)) continue;
  if (listings.filter((item) => item.source === 'GitHub bounty').length >= 6) break;
  add({
    source: 'GitHub bounty',
    title,
    url: issue.html_url,
    createdAt: issue.updated_at || issue.created_at || '',
    text: body,
  });
}

if (!listings.length) {
  throw new Error('PROJECT_FINDER: no listings. ' + (errors.join(' | ') || 'Sources returned nothing.'));
}

const maxListings = Math.min(40, Math.max(5, Number(config.maxListings) || 30));
return [{
  json: {
    siteBaseUrl: String(config.siteBaseUrl || 'https://silentcpo.me').replace(/\/$/, ''),
    openAiModel: config.openAiModel || 'gpt-4o-mini',
    minScore: Number(config.minScore) || 7,
    collectedAt: new Date().toISOString(),
    sourceErrors: errors,
    considered: listings.length,
    listings: listings.slice(0, maxListings),
  },
}];

const api = $input.first().json;
const meta = $('Build scoring prompt').first().json;
const content = api.choices?.[0]?.message?.content;
if (!content) throw new Error('OpenAI: empty project shortlist');

let parsed;
try {
  parsed = JSON.parse(content);
} catch {
  throw new Error('OpenAI: shortlist was not valid JSON');
}

function cleanUrl(value) {
  let raw = String(value || '').trim().split('#')[0];
  if (!raw.startsWith('https://')) return '';
  const q = raw.indexOf('?');
  const base = (q === -1 ? raw : raw.slice(0, q)).replace(/\/$/, '');
  if (q === -1) return base;
  const kept = raw.slice(q + 1).split('&').filter((part) => {
    const key = part.split('=')[0];
    return key && key.slice(0, 4) !== 'utm_' && key !== 'ref';
  });
  return kept.length ? base + '?' + kept.join('&') : base;
}

const listings = meta.listings || [];
const allowed = new Map(listings.map((item) => [cleanUrl(item.url), item]));
const minScore = Number(meta.minScore) || 6;
const returned = Array.isArray(parsed.picks) ? parsed.picks : [];
const dropped = { unmatched: 0, lowScore: 0 };
const picks = returned
  .map((pick) => {
    const ref = listings[Math.round(Number(pick.ref)) - 1];
    const source = allowed.get(cleanUrl(pick.url)) || ref;
    if (!source) {
      dropped.unmatched += 1;
      return null;
    }
    const url = cleanUrl(source.url);
    const score = Math.round(Number(pick.score));
    if (!Number.isFinite(score) || score < minScore) {
      dropped.lowScore += 1;
      return null;
    }
    const email = String(pick.contactEmail || '').trim();
    return {
      url,
      title: String(pick.title || source.title).slice(0, 180),
      source: String(source.source || '').slice(0, 80),
      score,
      budget: String(pick.budget || '').trim().slice(0, 80),
      why: String(pick.why || '').trim().slice(0, 500),
      replyAngle: String(pick.replyAngle || '').trim().slice(0, 2000),
      contactEmail: /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email) ? email.slice(0, 200) : '',
      excerpt: String(source.text || '').slice(0, 2000),
    };
  })
  .filter(Boolean)
  .filter((pick, index, all) => all.findIndex((other) => other.url === pick.url) === index)
  .sort((a, b) => b.score - a.score);

return [{
  json: {
    siteBaseUrl: String(meta.siteBaseUrl || 'https://silentcpo.me').replace(/\/$/, ''),
    listingsScored: listings.length,
    aiReturned: returned.length,
    dropped,
    saving: picks.length,
    saveBody: { picks },
  },
}];
